typedef unsigned long long big_int;

class stringx;

class string_buf
{
    friend class stringx;
    friend bool operator==(const stringx &, const stringx &);

    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;

public:
    bool is_equal(const string_buf &buf) const
    {
        if (buf.block_length != block_length)
            return false;
        for (int i = 0; i < block_length; i++)
            if (!(buf.data[i] == data[i]))
                return false;
        return true;
    }
};

class stringx
{
    friend bool operator==(const stringx &, const stringx &);

    char *chars;
    string_buf *my_buf;

public:
    stringx(const char *, int = -1);
    ~stringx();
};

inline bool operator==(const stringx &lhs, const stringx &rhs)
{
    return lhs.my_buf->is_equal(*rhs.my_buf);
}

enum
{
    CHEAT_LAST = 22,
    CHEAT_INVALID_CODE = -1,
    CHEAT_ALREADY_UNLOCKED = -2
};

class Cheat
{
    bool locked;
    bool on;

public:
    void setLockedState(const bool l) { locked = l; }
    void turnOn(const bool turn_on) { on = turn_on; }
    static int checkCodeUnlock(const stringx check);
};

class GlobalDataClass
{
public:
    bool isCheatUnlocked(int whichCheat) const;
};

extern const char *CheatCode[CHEAT_LAST];
extern Cheat g_session_cheats[CHEAT_LAST];
extern GlobalDataClass globalCareerData;
extern void debug_print(const char *, ...);

int Cheat::checkCodeUnlock(const stringx check)
{
    int i;
    for(i = 0; i < CHEAT_LAST; i++)
        if(CheatCode[i] == check)
        {
            if(globalCareerData.isCheatUnlocked(i))
                return CHEAT_ALREADY_UNLOCKED;
            g_session_cheats[i].setLockedState(false);
            g_session_cheats[i].turnOn(true);
            debug_print("Unlocked cheat #%d with the following code: %s\n", i, CheatCode[i]);
            return i;
        }

    return CHEAT_INVALID_CODE;
}
